"""Meet attendance checker — detects active accepted meetings the user has not joined.

Uses the Google Meet API via gws CLI to check conference records and participant
lists for currently-in-progress meetings.
"""

from __future__ import annotations

import json
import logging
import re
import subprocess
from datetime import datetime, timezone
from typing import Any

from personal_assistant.config import GWS_BINARY
from personal_assistant.types import CalendarEvent, ConferenceRecord

logger = logging.getLogger(__name__)


def _extract_meeting_code(hangout_link: str) -> str | None:
    """Extract the meeting code from a Google Meet URL."""
    # e.g. https://meet.google.com/abc-defg-hij
    match = re.search(r"meet\.google\.com/([a-z]+-[a-z]+-[a-z]+)", hangout_link)
    return match.group(1) if match else None


def _run_gws(
    args: list[str], timeout: int = 15
) -> dict[str, Any] | None:  # noqa: ARG001
    """Run a gws command and return parsed JSON, or None on failure."""
    try:
        result = subprocess.run(
            [GWS_BINARY] + args,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        if result.returncode != 0:
            return None
        parsed: dict[str, Any] = json.loads(result.stdout)
        return parsed
    except (subprocess.TimeoutExpired, json.JSONDecodeError, FileNotFoundError):
        return None


def _get_user_id() -> str | None:
    """Get the authenticated user's resource ID (numeric) from People API."""
    data = _run_gws(
        [
            "people",
            "people",
            "get",
            "--params",
            json.dumps(
                {
                    "resourceName": "people/me",
                    "personFields": "names",
                }
            ),
        ]
    )
    if not data:
        return None
    # resourceName is "people/<numeric_id>"
    resource: str = data.get("resourceName", "")
    if resource.startswith("people/"):
        return resource.split("/", 1)[1]
    return None


def _find_conference_record(meeting_code: str) -> ConferenceRecord | None:
    """Find the conference record for a meeting code."""
    data = _run_gws(
        [
            "meet",
            "conferenceRecords",
            "list",
            "--params",
            json.dumps(
                {
                    "filter": f'space.meeting_code="{meeting_code}"',
                }
            ),
            "--format",
            "json",
        ]
    )
    if not data:
        return None
    records: list[ConferenceRecord] = data.get("conferenceRecords", [])
    if not records:
        return None
    # Return the most recent (first) record
    return records[0]


def _user_in_participants(conference_name: str, user_id: str) -> bool:
    """Check if the user is in the participant list for a conference."""
    data = _run_gws(
        [
            "meet",
            "conferenceRecords",
            "participants",
            "list",
            "--params",
            json.dumps({"parent": conference_name}),
            "--format",
            "json",
        ]
    )
    if not data:
        return False
    participants = data.get("participants", [])
    # Participant signedinUser.user is "users/<numeric_id>"
    user_ref = f"users/{user_id}"
    return any(p.get("signedinUser", {}).get("user") == user_ref for p in participants)


def check_missed_meetings(
    today_events: list[CalendarEvent],
) -> list[CalendarEvent]:
    """Check for active accepted meetings the user has not joined.

    Returns a list of event dicts for meetings that are:
    - Currently in progress (start <= now < end)
    - User accepted (responseStatus == "accepted")
    - Have a Google Meet link
    - User has NOT joined according to Meet API participants
    """
    now = datetime.now(timezone.utc)
    candidates: list[CalendarEvent] = []

    for event in today_events:
        # Must have a Meet link
        hangout_link = event.get("hangout_link")
        if not hangout_link:
            continue

        # Must be in progress
        start_str = event.get("start", "")
        end_str = event.get("end", "")
        if not start_str or not end_str:
            continue

        try:
            start_dt = datetime.fromisoformat(start_str)
            end_dt = datetime.fromisoformat(end_str)
        except ValueError:
            continue

        if not (start_dt <= now < end_dt):
            continue

        # Must be accepted by user
        user_att = next(
            (a for a in event.get("attendees", []) if a.get("self")),
            None,
        )
        if not user_att:
            continue
        if user_att.get("response_status") != "accepted":
            continue

        candidates.append(event)

    if not candidates:
        return []

    # Get user ID once for all checks
    user_id = _get_user_id()
    if not user_id:
        logger.warning("Could not resolve user ID for Meet attendance check")
        return []

    missed: list[CalendarEvent] = []
    for event in candidates:
        hangout_link = event.get("hangout_link")
        if not hangout_link:
            continue
        meeting_code = _extract_meeting_code(hangout_link)
        if not meeting_code:
            continue

        record = _find_conference_record(meeting_code)
        if not record:
            # No conference record = meeting hasn't started on Meet yet
            # Still flag it — the meeting time says it should be active
            missed.append(event)
            continue

        # Check if meeting is still active (no endTime)
        if "endTime" in record:
            continue

        conf_name = record.get("name", "")
        if not _user_in_participants(conf_name, user_id):
            missed.append(event)

    return missed
